const main = document.querySelector('main');
const nav = document.querySelector('#nav');
const menu = document.querySelector('.menu-button');
const dialog = document.querySelector('#dialog');
const image = (name, alt, cls = '') => `<img class="${cls}" src="/assets/${name}.webp" alt="${alt}" loading="lazy" width="${['reading','creative','sport'].includes(name)?1600:1536}" height="${['reading','creative','sport'].includes(name)?800:1024}">`;
const icon = (name) => {const paths={art:'M4 20 14 10m-5 5 4 4M14 10l3-3a4 4 0 0 1 6 6l-3 3M4 20l-1 5 5-1 12-12',sport:'M15 3a12 12 0 1 0 0 24 12 12 0 0 0 0-24ZM3 15h24M15 3c7 7 7 17 0 24M15 3c-7 7-7 17 0 24',science:'M11 3h8M12 3v9L4 24a2 2 0 0 0 2 3h18a2 2 0 0 0 2-3l-8-12V3M8 20h14',care:'M15 26 4 15a7 7 0 0 1 11-9 7 7 0 0 1 11 9L15 26Z'};return `<svg viewBox="0 0 30 30" aria-hidden="true"><path d="${paths[name]}"/></svg>`};
const cta = () => `<section class="section"><div class="container"><div class="cta reveal"><div><span class="eyebrow">THE START OF SOMETHING SPECIAL</span><h2>Come as you are.<br>See who you could become.</h2><p>Meet our people, explore the classrooms, and imagine your child’s next chapter.</p></div><div class="actions"><a class="button navy" href="#visit">Plan your visit</a><a class="button outline" href="#admissions">Explore admissions</a></div></div></div></section>`;
const banner = (label,title,desc,dark=false) => `<section class="page-banner ${dark?'navy-banner':''}"><div class="breadcrumb"><a href="#home">Home</a> / ${label}</div><span class="eyebrow">${label.toUpperCase()}</span><h1>${title}</h1><p>${desc}</p></section>`;
const schoolCards = () => `<div class="school-grid"><article class="school-card reveal"><div class="school-image">${image('primary','Primary pupils learning together with their teacher')}<span class="badge">PRIMARY · YEARS 1–6</span></div><div class="school-card-body"><h3>Small steps.<br>Wonderful discoveries.</h3><p>A joyful foundation in reading, numbers and the world around us. Every question matters. Every child belongs.</p><div class="card-bottom"><span>Ages 5–11</span><a class="button outline" href="#primary">Explore primary</a></div></div></article><article class="school-card reveal"><div class="school-image">${image('secondary','Secondary pupils exploring science in a supervised laboratory')}<span class="badge">SECONDARY · JSS 1–SSS 3</span></div><div class="school-card-body"><h3>Bigger questions.<br>Brighter possibilities.</h3><p>Subject depth, independent thinking and the confidence to take the next step. Learning with purpose, inside and beyond the classroom.</p><div class="card-bottom"><span>Ages 11–17</span><a class="button outline" href="#secondary">Explore secondary</a></div></div></article></div>`;
const photoStories=()=>`<div class="photo-stories">${[['creative','Pupils exploring painting and collage with their teacher','Room to create','Ideas take shape through colour, craft and shared discovery.'],['sport','Secondary pupils practising basketball together outdoors','Space to play','Movement and teamwork bring a different kind of learning.'],['reading','Pupils reading together at an accessible library table','Time to explore','A good book, a new question and a place for every learner.']].map(([img,alt,h,p])=>`<figure class="photo-story">${image(img,alt)}<figcaption><h3>${h}</h3><p>${p}</p></figcaption></figure>`).join('')}</div>`;
const lifeTiles = () => `<div class="life-tiles">${[['art','Find your expression','Art, music and the confidence to create.'],['sport','Move. Play. Belong.','Teamwork, movement and healthy competition.'],['science','Follow your curiosity','Experiments, coding and hands-on discovery.'],['care','Feel seen. Feel safe.','A caring community that knows every child.']].map(([i,h,p])=>`<article class="life-tile">${icon(i)}<div><h3>${h}</h3><p>${p}</p></div></article>`).join('')}</div>`;
const faqs=[['What is the difference between primary and secondary?','Primary builds strong foundations through guided, hands-on learning. Secondary develops deeper subject knowledge, independent study and preparation for external examinations.'],['How do I know which year group is right for my child?','Start with your child’s age, most recent school year and learning needs. A conversation with the admissions team and an age-appropriate assessment help determine a suitable placement.'],['What should I ask about fees?','Ask for the current fee schedule for your child’s year group, including tuition, meals, transport, clubs, uniforms and any one-off charges. Confirm payment dates and refund terms before accepting a place.'],['Can my child join from another school?','Ask the school about transfer availability for your child’s year group. Bring recent reports to discuss placement, learning needs and the transition.'],['What happens during a school visit?','A visit is a chance to see learning spaces, discuss the curriculum and ask about daily routines, student support and admissions. Use the visit planner to prepare questions for your family.']];
const faqBlock=()=>`<div>${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
const learningData = {
primary:{title:'A strong foundation. A curious mind.',description:'Literacy and numeracy give children the tools to explore. Practical lessons, thoughtful questions and creative projects help them connect what they learn to everyday life.',subjects:['English & literacy','Mathematics','Science','Social studies','Creative arts','Physical education'],img:'primary',alt:'Primary students developing skills through hands-on classroom learning'},
secondary:{title:'Knowledge with depth. Learning with purpose.',description:'A broad junior secondary foundation leads into focused senior study. Students practise research, problem-solving and thoughtful discussion, with guidance as they prepare for their next stage.',subjects:['English language','Mathematics','Sciences','Humanities','Technology','Arts & languages'],img:'secondary',alt:'Secondary students in a practical science lesson'}
};
const learningContent=(key)=>{const d=learningData[key];return `${image(d.img,d.alt)}<div><h3>${d.title}</h3><p>${d.description}</p><div class="subject-list">${d.subjects.map(s=>`<span>${s}</span>`).join('')}</div><div class="actions"><a class="button navy" href="#${key}">Discover the curriculum</a></div></div>`};
const pages = {
home:()=>`<section class="hero"><div class="hero-panel"><div class="hero-copy"><span class="eyebrow"><span class="eyebrow-line"></span>A SCHOOL FOR WHO THEY WILL BECOME</span><h1>Bright minds.<br>Big hearts.<br><em>Boundless futures.</em></h1><p>A primary and secondary school where children are known, curiosity is encouraged, and potential has room to grow.</p><div class="actions"><a class="button navy" href="#admissions">Explore admissions</a><a class="button outline" href="#about">Get to know us</a></div></div><div class="hero-photo"><img src="/assets/students.webp" alt="Three students sharing a happy moment on the school campus" width="1536" height="1024" fetchpriority="high"><div class="photo-label"><div><strong>Room to learn. Space to become.</strong><small>Primary & secondary · A shared journey</small></div><span class="seal">CW</span></div></div></div><div class="hero-foot"><span><b>One school. Every possibility.</b></span><span>01 <b>Academic growth</b></span><span>02 <b>Character & care</b></span><span>03 <b>Life beyond lessons</b></span></div></section>
<section class="section"><div class="container intro"><div class="intro-visual"><span class="eyebrow">THE CRESTWOOD WAY</span>${image('reading','Children sharing a book in a welcoming school library','story-image')}</div><div class="reveal"><h2>An education that opens minds.<br><span>And a community that opens arms.</span></h2><p class="intro-text">A child’s education is more than the lessons they learn. It is the questions they dare to ask, the friendships they make, and the person they begin to become. At Crestwood, we make room for all of it.</p><div class="principles"><span>Curiosity<small>Ask. Explore. Discover.</small></span><span>Character<small>Kindness in action.</small></span><span>Possibility<small>Confidence for what’s next.</small></span></div></div></div></section>
<section class="section schools"><div class="container"><div class="section-heading"><div><span class="eyebrow">TWO CHAPTERS. ONE EXTRAORDINARY JOURNEY.</span><h2>The right start.<br>The room to grow.</h2></div><p>From first discoveries to future ambitions, an education that grows with your child.</p></div>${schoolCards()}</div></section>
<section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">MORE THAN A CLASSROOM</span><h2>A school day.<br>A world of discovery.</h2></div><p>There is more than one way to shine. We help every child find theirs.</p></div><div class="life-grid"><article class="life-feature reveal">${image('sport','Students enjoying a basketball passing drill outdoors','life-feature-photo')}<div><span class="eyebrow">LIFE AT CRESTWOOD</span><h2>Some of the best lessons happen beyond the timetable.</h2><p>A new interest. A shared challenge. A small act of kindness. The experiences that shape a school day shape a life, too.</p></div><a class="button light" href="#school-life">Explore school life</a><span class="large-index" aria-hidden="true">C</span></article>${lifeTiles()}</div></div></section>
<section class="section learning"><div class="container"><div class="learning-top"><div><span class="eyebrow">A THOUGHTFUL APPROACH TO LEARNING</span><h2>Built on foundations.<br>Inspired by possibility.</h2></div><p>Clear learning goals, meaningful feedback and space to explore. Discover how our approach evolves as children grow.</p></div><div class="tabs" role="tablist" aria-label="Explore school curriculum"><button id="tab-primary" role="tab" aria-selected="true" aria-controls="learning-panel" tabindex="0" data-tab="primary">Primary school</button><button id="tab-secondary" role="tab" aria-selected="false" aria-controls="learning-panel" tabindex="-1" data-tab="secondary">Secondary school</button></div><div id="learning-panel" class="learning-panel" role="tabpanel" aria-labelledby="tab-primary" tabindex="0">${learningContent('primary')}</div></div></section>
<section class="quote-section reveal"><span class="eyebrow">OUR BELIEF</span><div class="quote-mark" aria-hidden="true">“</div><blockquote>When children feel they belong,<br>they find the confidence to become.</blockquote><p>The principle at the heart of Crestwood.</p></section>
<section class="section faq-section"><div class="container faq-layout"><div class="faq-intro"><span class="eyebrow">A LITTLE MORE CLARITY</span><h2>Big decisions.<br>Good questions.</h2><p>Choosing a school matters. Here is a useful place to begin.</p><a class="button outline" href="#admissions">Your admissions guide</a></div>${faqBlock()}</div></section>${cta()}`,
about:()=>`${banner('Our school','A place to belong.<br>A space to become.','We believe children do their best learning when they feel safe, supported and inspired to ask what comes next.')}<section class="section"><div class="container">${image('students','Students enjoying friendship on campus','detail-image')}<div class="two-col"><div><span class="eyebrow">OUR PURPOSE</span><h2>Growing minds.<br>Building character.</h2><p>Our purpose is to help children become thoughtful learners and confident people. Academic progress and personal growth belong together.</p></div><div><p>We see school as a partnership between children, educators and families. Good communication helps each child feel understood, and thoughtful teaching helps them make steady progress.</p><p>Across primary and secondary, we encourage curiosity, respect and responsibility. Children learn to listen, work together and take pride in their effort.</p></div></div><div class="detail-grid">${[['Curiosity','A good question is the beginning of discovery. We make space for exploration, discussion and creative thinking.'],['Character','Kindness, honesty and responsibility grow through daily choices, shared routines and caring relationships.'],['Possibility','Every child has different strengths. We help them recognise those strengths and build the confidence to try something new.']].map(([h,p])=>`<article class="detail-card"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="section learning"><div class="container two-col"><div><span class="eyebrow">CARE THAT SUPPORTS LEARNING</span><h2>Known as a person.<br>Supported as a learner.</h2>${image('reading','Children learning together at an accessible library table','story-image')}</div><div><p>Pastoral support starts with everyday relationships. Children need trusted adults, clear routines and a way to ask for help.</p><ul class="feature-list"><li><span class="number">01</span><div><b>A welcoming transition</b><small>Orientation and classroom routines that help new pupils settle.</small></div></li><li><span class="number">02</span><div><b>Learning support</b><small>Early conversations about strengths, challenges and suitable support.</small></div></li><li><span class="number">03</span><div><b>A family partnership</b><small>Clear feedback and opportunities to discuss your child’s progress.</small></div></li></ul></div></div></section>${cta()}`,
primary:()=>schoolPage('primary'),
secondary:()=>schoolPage('secondary'),
'school-life':()=>`${banner('School life','More ways to discover.<br>More reasons to belong.','School life is where interests become passions, classmates become friends, and children discover what they can do.',true)}<section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">BEYOND THE LESSON</span><h2>Find your thing.<br>Then find something new.</h2></div><p>A balanced week makes room for creativity, movement, practical discovery and time together.</p></div>${photoStories()}${lifeTiles()}<div class="article-list">${[['CREATIVE LIFE','Arts, music & performance','From sketchbooks to the stage, children develop the confidence to express ideas and share their work.','arts'],['ACTIVE LIFE','Sport & teamwork','Movement builds healthy habits. Team activities encourage perseverance, fairness and consideration for others.','sport'],['CURIOUS LIFE','Science, technology & making','Hands-on projects connect ideas to the real world. Students learn to test, revise and explain their thinking.','science'],['COMMUNITY LIFE','Leadership & service','Taking responsibility in small ways helps children become considerate members of their community.','community']].map(([l,h,p,k])=>`<article class="article-row"><span>${l}</span><div><h3>${h}</h3><p>${p}</p></div><button class="button outline" data-detail="${k}">Explore ${k==='arts'?'creative activities':k==='sport'?'sports activities':k==='science'?'science activities':'community activities'}</button></article>`).join('')}</div></div></section><section class="section learning"><div class="container two-col"><div><span class="eyebrow">EVERYDAY WELLBEING</span><h2>Care is part<br>of the school day.</h2></div><div><p>Learning takes confidence. Clear routines, supportive adults and a sense of belonging give children a secure place to grow.</p><ul class="feature-list"><li><span class="number">01</span><div><b>Friendship & belonging</b><small>Making space for shared experiences and respectful relationships.</small></div></li><li><span class="number">02</span><div><b>A healthy balance</b><small>Time for learning, movement, breaks and creative expression.</small></div></li><li><span class="number">03</span><div><b>Help when it matters</b><small>Encouraging students to speak with a trusted adult when they need support.</small></div></li></ul></div></div></section>${cta()}`,
admissions:()=>`${banner('Admissions','Their next chapter<br>starts with a conversation.','Take time to explore, ask questions and find the right fit for your child. We will guide you through the steps.')}<section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">A CLEAR PATH FOR YOUR FAMILY</span><h2>From first question<br>to first school day.</h2></div><a class="button navy" href="#visit">Prepare a school visit</a></div><div class="process">${[['01','Explore & enquire','Read about the school and consider your child’s interests, learning needs and current year group.'],['02','Visit & meet','Explore the learning spaces, meet the team and ask about the things that matter to your family.'],['03','Apply & assess','Confirm entry requirements, provide recent reports and arrange the appropriate assessment.'],['04','Accept & settle','Review your offer and fee schedule, then plan a welcoming transition into school.']].map(([n,h,p])=>`<article><div class="step">${n}</div><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="section schools"><div class="container two-col"><div><span class="eyebrow">BEFORE YOU APPLY</span><h2>Make your next step<br>a confident one.</h2><p>Use the guide to prepare your questions and documents. Final requirements depend on the year group and the school’s admissions policy.</p></div><div class="form"><h3>Your admissions checklist</h3><p>Choose a school stage to see what to prepare.</p><label>School stage<select id="stage-select"><option value="primary">Primary school · Years 1–6</option><option value="secondary">Secondary school · JSS 1–SSS 3</option></select></label><div id="checklist">${checklist('primary')}</div><button class="button navy" id="download-checklist">Download checklist</button><p class="form-status" id="download-status" role="status"></p></div></div></section><section class="section"><div class="container faq-layout"><div class="faq-intro"><span class="eyebrow">ANSWERS FOR YOUR NEXT STEP</span><h2>A little clarity<br>goes a long way.</h2></div>${faqBlock()}</div></section>${cta()}`,
visit:()=>`${banner('Visit planner','Get a feel for<br>your child’s next chapter.','Prepare your questions with a personal visit plan. This tool does not book a visit; arrange a time directly with the school.')}<section class="section"><div class="container visit-layout"><aside class="visit-aside"><span class="eyebrow">MAKE THE MOST OF YOUR VISIT</span><h2>See it.<br>Ask it.<br>Imagine it.</h2><p>Your school visit should help you picture a real day for your child.</p><ul><li>Explore classrooms and learning spaces.</li><li>Discuss the curriculum and learning support.</li><li>Ask about clubs, care and daily routines.</li><li>Review admissions steps and the fee schedule.</li></ul><p>Bring recent school reports if you would like to discuss a transfer.</p>${image('students','Students talking together on a school campus','visit-photo')}</aside><form id="visit-form" class="form"><h2>Your family’s visit planner</h2><p>This planner helps you prepare. It does not book a visit or send your details to the school.</p><label>School stage<select name="stage"><option value="Primary school">Primary school</option><option value="Secondary school">Secondary school</option><option value="Both primary and secondary">Both primary and secondary</option></select></label><div class="form-row"><label>Preferred visit date<input type="date" name="date" required></label><label>Your main interest<select name="interest"><option>Curriculum & teaching</option><option>Student care & support</option><option>School life & activities</option><option>Admissions & fees</option></select></label></div><label>Questions you would like to ask <span style="font-weight:400">(optional)</span><textarea name="questions" maxlength="1000" placeholder="What would help you decide if this is the right school?"></textarea></label><button class="button navy" type="submit">Create my visit plan</button><div id="visit-result" aria-live="polite"></div></form></div></section>`,
privacy:()=>`${banner('Privacy & cookies','Your information.<br>Your choice.','A clear explanation of how this website’s tools work.')}<section class="section"><div class="container" style="max-width:850px"><h2>Privacy on this website</h2><div class="notice">The visit planner creates a plan in your browser. It does not send a booking or personal information to the school.</div><h3>Visit plans & checklists</h3><p style="margin:18px 0 30px">Your selections and questions stay in the current page while you use it. You can download them as a text file. They are not stored in an admissions database and are cleared when the page reloads.</p><h3>Fonts & hosting</h3><p style="margin:18px 0 30px">The website uses locally hosted fonts and images. The hosting provider may process technical information needed to serve pages and manage access. This website does not add advertising cookies or analytics trackers.</p><h3>School admissions</h3><p style="margin-top:18px">Formal applications and confirmed visit bookings require the school’s official admissions service. This site’s preparation tools do not submit an application.</p><div class="actions"><a class="button navy" href="#home">Return to the school</a></div></div></section>`
};
function schoolPage(key){const isP=key==='primary';const title=isP?'Small steps.<br>Extraordinary beginnings.':'Growing independence.<br>Expanding horizons.';const desc=isP?'A joyful, purposeful primary education that nurtures confidence, curiosity and a love of learning.':'A secondary education that develops subject knowledge, independent thinking and confidence for life beyond school.';return `${banner(isP?'Primary school':'Secondary school',title,desc,!isP)}<section class="section"><div class="container">${image(key,isP?'Young learners working with their teacher in a bright classroom':'Secondary students exploring chemistry with their teacher','detail-image')}<div class="two-col"><div><span class="eyebrow">${isP?'AGES 5–11 · YEARS 1–6':'AGES 11–17 · JSS 1–SSS 3'}</span><h2>${isP?'A foundation for<br>a lifetime of learning.':'A new level of learning.<br>A stronger sense of self.'}</h2><p>${learningData[key].description}</p><div class="actions"><a href="#admissions" class="button navy">Explore entry to ${key}</a></div></div><div><h3>${isP?'How young minds grow':'How we support the next step'}</h3><ul class="feature-list">${(isP?[['Strong foundations','Reading, writing and mathematics taught with clear goals and thoughtful practice.'],['Hands-on discovery','Experiments, stories and projects that make ideas memorable.'],['Confidence & care','Supportive routines, friendships and opportunities to celebrate effort.']]:[['Deeper subject knowledge','Structured study, practical application and meaningful feedback.'],['Growing independence','Study habits, research skills and responsibility for learning.'],['Future preparation','Guidance through subject choices, examination preparation and next-step planning.']]).map(([h,p],i)=>`<li><span class="number">0${i+1}</span><div><b>${h}</b><small>${p}</small></div></li>`).join('')}</ul></div></div></div></section><section class="section learning"><div class="container"><div class="section-heading"><div><span class="eyebrow">THE CURRICULUM</span><h2>${learningData[key].title}</h2></div></div><div class="subject-list">${learningData[key].subjects.map(s=>`<span>${s}</span>`).join('')}</div><div class="detail-grid">${(isP?[['Lower primary','Years 1–3','Developing reading fluency, number confidence and positive learning routines through guided exploration.'],['Upper primary','Years 4–6','Extending understanding, building independence and learning to explain ideas with growing confidence.'],['Moving forward','The transition to secondary','Preparing for new subjects, new responsibilities and the next stage with encouragement and continuity.']]:[['Junior secondary','Junior secondary school · JSS 1–3','Building a broad foundation across languages, mathematics, sciences, technology and humanities.'],['Senior secondary','Senior secondary school · SSS 1–3','Deepening knowledge in selected subjects, strengthening independent study and preparing for external examinations.'],['Beyond school','Preparing for what comes next','Developing practical skills, thoughtful ambitions and an informed approach to further education and career choices.']]).map(([h,s,p])=>`<article class="detail-card"><span class="eyebrow">${s}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section><section class="section"><div class="container two-col"><div><span class="eyebrow">LEARNING IS A PARTNERSHIP</span><h2>Progress you can understand.<br>Support you can rely on.</h2>${image(isP?'creative':'sport',isP?'Young pupils creating art with their teacher':'Secondary pupils practising teamwork on a basketball court','story-image')}</div><div><p>Regular feedback helps children recognise what they have learned and what to work on next. Family conversations connect classroom progress with the support children receive at home.</p><p>Ask about reporting, teacher meetings and learning support when you visit. A clear understanding of your child’s needs is a valuable starting point.</p><div class="actions"><a href="#visit" class="button outline">Prepare your questions</a></div></div></div></section>${cta()}`;}
function checklist(key){return `<ul class="feature-list">${(key==='primary'?['Confirm the appropriate year group and entry age.','Prepare a recent school report, if applicable.','Ask how reading and numeracy are assessed.','Discuss learning support and settling-in routines.','Request the current fee schedule and document list.']:['Confirm entry availability for junior or senior secondary.','Prepare recent reports and relevant exam results.','Ask about placement assessment and subject choices.','Discuss transfer support and examination preparation.','Request the current fee schedule and document list.']).map((s,i)=>`<li><span class="number">0${i+1}</span><div>${s}</div></li>`).join('')}</ul>`;}
const activities={arts:['Arts, music & performance',['Explore drawing, painting and design.','Ask about music lessons and ensemble opportunities.','Discover drama, public speaking and performance.'],'Creative experiences help students practise, collaborate and share ideas with confidence.'],sport:['Sport & teamwork',['Explore the PE programme and sports facilities.','Ask about team activities and age-appropriate training.','Discuss inclusion, supervision and healthy routines.'],'A thoughtful sports programme values participation, progress and fair play.'],science:['Science, technology & making',['Ask about practical science and laboratory supervision.','Explore coding, digital literacy and maker projects.','Discover how students test ideas and present their findings.'],'Practical discovery turns a lesson into an experience students can understand and explain.'],community:['Leadership & service',['Ask about student responsibilities and leadership.','Explore community projects and service opportunities.','Discover how the school develops respect and belonging.'],'Small responsibilities create meaningful opportunities to contribute.']};
function downloadFile(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setMenu(open){nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView({behavior:'instant',block:'start'});});
menu.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true'));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){const restore=nav.contains(document.activeElement);setMenu(false);if(restore&&menu.getClientRects().length)menu.focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('header'))setMenu(false)});
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
let observer;
function bindPage(){
 const tabs=[...document.querySelectorAll('[data-tab]')];
 function activateTab(btn){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===btn));t.tabIndex=t===btn?0:-1});const panel=document.querySelector('#learning-panel');panel.innerHTML=learningContent(btn.dataset.tab);panel.setAttribute('aria-labelledby',btn.id);}
 tabs.forEach((b,i)=>{b.addEventListener('click',()=>activateTab(b));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;activateTab(tabs[n]);tabs[n].focus();}})});
 const stage=document.querySelector('#stage-select');if(stage){stage.addEventListener('change',()=>{document.querySelector('#checklist').innerHTML=checklist(stage.value);document.querySelector('#download-status').textContent='';});document.querySelector('#download-checklist').addEventListener('click',()=>{downloadFile(`crestwood-${stage.value}-admissions-checklist.txt`,`CRESTWOOD SCHOOL\n${stage.value.toUpperCase()} ADMISSIONS CHECKLIST\n\n${document.querySelector('#checklist').innerText}\n\nConfirm all requirements and fees with the school before applying.`);document.querySelector('#download-status').textContent='Your checklist is ready to save.';});}
 const form=document.querySelector('#visit-form');if(form){const date=form.elements.date;const today=new Date();const local=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;date.min=local;form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);const dateValue=new Date(`${data.get('date')}T12:00:00`);const label=dateValue.toLocaleDateString('en-NG',{weekday:'long',day:'numeric',month:'long',year:'numeric'});const r=document.querySelector('#visit-result');r.innerHTML='<div class="plan-result"><h4>Your visit plan is ready.</h4><p id="plan-summary"></p><p>This is a preparation plan. Your visit has not been booked. Confirm the date directly with the school.</p><button class="button navy" id="save-plan" type="button" style="margin-top:20px">Download my plan</button></div>';r.querySelector('#plan-summary').textContent=`${data.get('stage')} · ${label} · Focus: ${data.get('interest')}`;r.querySelector('#save-plan').addEventListener('click',()=>downloadFile('crestwood-school-visit-plan.txt',`CRESTWOOD SCHOOL — YOUR VISIT PLAN\n\nSchool stage: ${data.get('stage')}\nPreferred date: ${label}\nMain interest: ${data.get('interest')}\n\nYour questions:\n${data.get('questions')||'No additional questions entered.'}\n\nRemember to ask about:\n- Curriculum and teaching\n- Pastoral care and learning support\n- Activities and daily routines\n- Entry requirements and fees\n\nThis is a preparation plan, not a confirmed booking. Confirm the date with the school.`));});}
 document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{const [h,items,p]=activities[b.dataset.detail];document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">${h}</h2><p>${p}</p><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul><p>Ask the school for its current activity timetable and availability.</p><div class="actions"><a href="#visit" class="button navy" id="dialog-visit">Prepare your visit</a></div>`;dialog.showModal();document.querySelector('#dialog-visit').addEventListener('click',()=>dialog.close());}));
 if(observer)observer.disconnect();if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.body.classList.add('motion-ready');observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('seen');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
}
function render(){let key=location.hash.slice(1)||'home';if(!pages[key])key='home';setMenu(false);if(dialog.open)dialog.close();main.innerHTML=pages[key]();main.classList.remove('main-enter');void main.offsetWidth;main.classList.add('main-enter');document.querySelectorAll('nav a').forEach(a=>{if(a.getAttribute('href')===`#${key}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=`${key==='home'?'Room to become':({'school-life':'School life',about:'Our school',visit:'Visit planner',privacy:'Privacy & cookies'}[key]||key[0].toUpperCase()+key.slice(1))} — Crestwood School`;bindPage();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});});document.querySelector('#year').textContent=new Date().getFullYear();render();
